import { readFileSync, readdirSync } from 'fs';

const dir = 'wiki/npcs';
const lx = 3222, lz = 3222;
const rows: any[] = [];
for (const f of readdirSync(dir)) {
  if (!f.endsWith('.md')) continue;
  const t = readFileSync(`${dir}/${f}`, 'utf8');
  const get = (re: RegExp) => { const m = t.match(re); return m ? m[1].trim() : ''; };
  const name = get(/^# (.+)$/m);
  const lvlS = get(/\*\*Combat Level\*\* \| ([^|]+)/);
  const hpS = get(/\*\*Hitpoints\*\* \| ([^|]+)/);
  const sd = parseInt(get(/\*\*Stab Defence\*\* \| (-?\d+)/) || '99');
  const sl = parseInt(get(/\*\*Slash Defence\*\* \| (-?\d+)/) || '99');
  const cr = parseInt(get(/\*\*Crush Defence\*\* \| (-?\d+)/) || '99');
  const nums = (s: string) => (s.match(/\d+/g) || []).map(Number);
  const lvls = nums(lvlS.replace(/-/g, ' '));
  const hps = nums(hpS);
  const maxLvl = lvls.length ? Math.max(...lvls) : 0;
  const minLvl = lvls.length ? Math.min(...lvls) : 0;
  // find closest location coord
  let best = Infinity, bxy = '';
  for (const m of t.matchAll(/\((\d{3,4}),\s*(\d{4,5})\)/g)) {
    const x = +m[1], z = +m[2];
    if (x < 3000 || x > 3600 || z < 3000 || z > 3600) continue;
    const d = Math.hypot(x - lx, z - lz);
    if (d < best) { best = d; bxy = `${x},${z}`; }
  }
  const def = Math.min(sd, sl, cr);
  if (def <= 5 && maxLvl >= 7 && maxLvl <= 30 && best < 220) {
    rows.push({ name, minLvl, maxLvl, hp: hps[0], def: [sd, sl, cr].join('/'), dist: Math.round(best), at: bxy });
  }
}
rows.sort((a, b) => (b.maxLvl - a.maxLvl) || (a.dist - b.dist));
console.log(JSON.stringify(rows, null, 0));

